INF = float('inf')

def _t():
    values = [complex(5.0, 12.0), complex(5e+100, 1.2e+101), complex(-4.0, INF), complex(INF, 0.0)]
    exponents = [-19, -5, -3, -2, -1, 0, 1, 2, 3, 5, 19]
    for value in values:
        for exponent in exponents:
            try:
                int_pow = value ** exponent
            except OverflowError:
                int_pow = 'overflow'
            try:
                float_pow = value ** float(exponent)
            except OverflowError:
                float_pow = 'overflow'
            try:
                complex_pow = value ** complex(exponent)
            except OverflowError:
                complex_pow = 'overflow'
            assert str(float_pow) == str(int_pow), ('assertEqual', str(float_pow), str(int_pow))
            assert str(complex_pow) == str(int_pow), ('assertEqual', str(complex_pow), str(int_pow))
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

